    async save(event) { this.saving = true; this.errors = []; try { const response = await fetch(event.target.action, { method: 'POST', body: new FormData(event.target), headers: { Accept: 'application/json', 'X-Requested-With': 'XMLHttpRequest' }, credentials: 'same-origin' }); const data = await response.json().catch(() => ({})); if (!response.ok) { this.errors = Object.values(data.errors || {}).flat(); if (!this.errors.length) this.errors = [data.message || 'Unable to save the room.']; return; } this.close(true); window.location.reload(); } catch (error) { this.errors = ['Unable to save the room. Please try again.']; } finally { this.saving = false; } },
